package com.nigson.commerce.notification;
import java.net.*;
import java.net.http.*;
import java.nio.ByteBuffer;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.Flow;
import java.util.function.Function;
import tools.jackson.databind.JsonNode;
import com.nigson.commerce.security.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.*;

/** Fixed experience phone-consent operations. Current browser authority never becomes a caller-supplied phone scope. */
public final class PhoneRelay {
 private final URI base;private final HttpClient http;private final Function<PrivateWorkload.Route,String> credentials;private final ActorDelegation delegation;private final JdbcSessionTrust sessions;private final CommerceAuthority authority;
 private static final tools.jackson.databind.json.JsonMapper JSON=tools.jackson.databind.json.JsonMapper.builder(tools.jackson.core.json.JsonFactory.builder().enable(tools.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).streamReadConstraints(tools.jackson.core.StreamReadConstraints.builder().maxNestingDepth(8).maxStringLength(65536).build()).build()).enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).build();
 public PhoneRelay(String env,String endpoint,Function<PrivateWorkload.Route,String> credentials,ActorDelegation delegation,JdbcSessionTrust sessions,CommerceAuthority authority){base=target(env,endpoint);this.credentials=Objects.requireNonNull(credentials);this.delegation=Objects.requireNonNull(delegation);this.sessions=Objects.requireNonNull(sessions);this.authority=Objects.requireNonNull(authority);http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).followRedirects(HttpClient.Redirect.NEVER).build();}
 public static URI target(String env,String endpoint){try{if(!Set.of("local","test","dev","qa","stage","prod").contains(env))throw new IllegalArgumentException();var u=URI.create(endpoint);boolean local=Set.of("local","test").contains(env);if(u.getHost()==null||u.getUserInfo()!=null||u.getRawQuery()!=null||u.getFragment()!=null||!Set.of("","/").contains(u.getRawPath())||u.getPort()==0||u.getPort()>65535||!(local?Set.of("http","https").contains(u.getScheme())&&Set.of("127.0.0.1","localhost","experience","experience-mock").contains(u.getHost()):"https".equals(u.getScheme())&&u.getHost().matches("[a-z0-9]+(?:[.-][a-z0-9]+)*\\.internal")))throw new IllegalArgumentException();return URI.create(u.getScheme()+"://"+u.getRawAuthority());}catch(RuntimeException invalid){throw new IllegalArgumentException("EXPERIENCE_TARGET_REQUIRED");}}
 private void current(ActorAssertion.Actor actor,String session){var now=authority.resolve(sessions.read(session,true),null,Set.of());if(actor==null||!now.party().equals(actor.party())||actor.organization()!=null||!now.roles().contains("CUSTOMER"))throw ActorAssertion.denied();}
 public record Result(int status,JsonNode body){}
 public Result execute(ActorAssertion.Actor actor,String session,String api,UUID id,JsonNode body,String key,UUID correlation){IdentityKeys.outsideTransaction();current(actor,session);if(!Set.of("API-201","API-202","API-203","API-204").contains(api)||correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals(api)&&r.client().equals("nigson-commerce")&&r.owner().equals("experience")).findFirst().orElseThrow(ActorAssertion::denied);String path=route.path();if(path.contains("{id}")){if(id==null||id.equals(new UUID(0,0)))throw ApiValues.invalid();path=path.replace("{id}",id.toString());}else if(id!=null)throw ApiValues.invalid();boolean read=route.method().equals("GET");if(!read)ApiValues.idempotencyKey(key);byte[] bytes=read?new byte[0]:EventCodec.JSON.writeValueAsBytes(body);if(bytes.length>8192)throw ApiValues.invalid();var binding=new ActorAssertion.Binding("experience",route.scope(),route.method(),path,correlation,ActorAssertion.Binding.bodyHash(bytes));String assertion,token;try{assertion=delegation.issue(session,binding,null);token=credentials.apply(route);}catch(org.springframework.security.access.AccessDeniedException denied){throw denied;}catch(RuntimeException unavailable){throw new Problem.Failure(ProblemCode.PROVIDER_UNAVAILABLE);}if(token==null||token.isBlank()||token.length()>16384)throw unavailable(read);var builder=HttpRequest.newBuilder(base.resolve(path)).timeout(Duration.ofSeconds(5)).header("Authorization","Bearer "+token).header("X-Nigson-Actor",assertion).header("X-Correlation-ID",correlation.toString()).header("Accept","application/json");if(!read)builder.header("Content-Type","application/json").header("Idempotency-Key",key);String trace=com.nigson.shared.observability.WireContext.traceparent();if(trace!=null)builder.header("traceparent",trace);var request=builder.method(route.method(),bytes.length==0?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofByteArray(bytes)).build();CompletableFuture<HttpResponse<byte[]>> future=null;try{future=http.sendAsync(request,info->new Limited());var response=future.get(6,TimeUnit.SECONDS);current(actor,session);int expected=api.equals("API-201")?201:api.equals("API-204")?204:200;if(response.statusCode()==204&&expected==204){if(response.body().length!=0)throw unavailable(read);return new Result(204,EventCodec.JSON.nullNode());}var types=response.headers().allValues("Content-Type");if(types.size()!=1)throw unavailable(read);String type=types.getFirst().split(";",2)[0].strip();var json=JSON.readTree(response.body());if(response.statusCode()!=expected){if(type.equals("application/problem+json"))for(var safe:List.of(ProblemCode.VALIDATION_ERROR,ProblemCode.AUTH_REQUIRED,ProblemCode.ACCESS_DENIED,ProblemCode.NOT_FOUND,ProblemCode.VERSION_MISMATCH,ProblemCode.INVALID_TRANSITION,ProblemCode.IDEMPOTENCY_HASH_MISMATCH,ProblemCode.IDEMPOTENCY_IN_PROGRESS,ProblemCode.CONSENT_RULE_VIOLATION,ProblemCode.FEATURE_DISABLED))if(response.statusCode()==safe.status&&safe.name().equals(json.path("code").asString()))throw new Problem.Failure(safe);throw unavailable(read);}if(!type.equals("application/json"))throw unavailable(read);if(read){if(!json.isArray()||json.size()>100)throw unavailable(read);var ids=new HashSet<UUID>();for(var item:json){validate(item,null);if(!ids.add(ApiValues.uuid(item.path("id").asString())))throw unavailable(read);}}else {validate(json,id);if(api.equals("API-202")&&!json.path("status").asString().equals("ACTIVE"))throw unavailable(false);}return new Result(expected,json);}catch(Problem.Failure failure){if(read&&failure.code==ProblemCode.PROVIDER_OUTCOME_UNKNOWN)throw unavailable(true);throw failure;}catch(org.springframework.security.access.AccessDeniedException denied){throw new Problem.Failure(ProblemCode.ACCESS_DENIED);}catch(Exception failure){if(failure instanceof InterruptedException)Thread.currentThread().interrupt();throw unavailable(read);}finally{if(future!=null&&!future.isDone())future.cancel(true);}}
 private static void validate(JsonNode node,UUID expected){if(node==null||!node.isObject()||!node.propertyNames().equals(Set.of("id","channel","maskedAddress","status","version")))throw unavailable(false);for(String name:List.of("id","channel","maskedAddress","status"))if(!node.path(name).isString())throw unavailable(false);UUID id=ApiValues.uuid(node.path("id").asString());if(expected!=null&&!expected.equals(id)||!Set.of("SMS","WHATSAPP").contains(node.path("channel").asString())||!node.path("maskedAddress").asString().matches("\\+234\\*{6}[0-9]{4}")||!Set.of("PENDING","ACTIVE","UNSUBSCRIBED","SUPPRESSED").contains(node.path("status").asString())||!node.path("version").isIntegralNumber()||!node.path("version").canConvertToLong()||node.path("version").asLong()<0)throw unavailable(false);}
 private static Problem.Failure unavailable(boolean read){return new Problem.Failure(read?ProblemCode.PROVIDER_UNAVAILABLE:ProblemCode.PROVIDER_OUTCOME_UNKNOWN);}
 private static final class Limited implements HttpResponse.BodySubscriber<byte[]> {private final CompletableFuture<byte[]> result=new CompletableFuture<>();private final java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();private Flow.Subscription subscription;public CompletionStage<byte[]> getBody(){return result;}public void onSubscribe(Flow.Subscription value){subscription=value;value.request(1);}public void onNext(List<ByteBuffer> chunks){for(var chunk:chunks){if(bytes.size()+chunk.remaining()>65536){subscription.cancel();result.completeExceptionally(new IllegalArgumentException("BODY_LIMIT"));return;}byte[] part=new byte[chunk.remaining()];chunk.get(part);bytes.writeBytes(part);}subscription.request(1);}public void onError(Throwable failure){result.completeExceptionally(failure);}public void onComplete(){result.complete(bytes.toByteArray());}}
}
